// Presentation only. Stable artwork/album decoration never changes stored records.
export const themes=['checker','flower','wavy','doodle'];
export function visualIndex(id,count=4){let hash=0;for(const char of String(id))hash=(hash*31+char.charCodeAt(0))>>>0;return hash%count;}
export const albumTheme=id=>themes[visualIndex(id)];
export function decoration(kind='flower',className=''){
  const petals=Array.from({length:6},(_,i)=>'<ellipse cx="60" cy="31" rx="17" ry="25" transform="rotate('+i*60+' 60 60)"/>').join('');
  const flower='<g fill="currentColor">'+petals+'</g><path d="M53 61q7 8 14 0" fill="none" stroke="var(--ink,#302B29)" stroke-width="3" stroke-linecap="round"/><g fill="var(--ink,#302B29)"><ellipse cx="51" cy="52" rx="6" ry="8" fill="#FFF9EE"/><ellipse cx="69" cy="52" rx="6" ry="8" fill="#FFF9EE"/><ellipse cx="53" cy="53" rx="3" ry="5"/><ellipse cx="71" cy="53" rx="3" ry="5"/></g>';
  const art={flower,star:'<path d="m60 8 9 35 34-16-22 32 29 20-37-3-9 36-14-33-34 12 21-29L10 40l37 3Z" fill="currentColor"/>',squiggle:'<path d="M8 65c15-75 28 75 44 0s29 75 42 0 18-30 19 0" fill="none" stroke="currentColor" stroke-width="9" stroke-linecap="round"/>',frame:'<rect x="14" y="13" width="88" height="94" rx="6" fill="var(--butter,#F7D55B)" transform="rotate(-6 60 60)"/><rect x="28" y="28" width="60" height="62" rx="2" fill="var(--paper,#FFFDF8)"/><path d="m38 75 16-22 12 13 11-15" fill="none" stroke="currentColor" stroke-width="4"/><circle cx="74" cy="42" r="6" fill="currentColor"/>',heart:'<path d="M60 96 20 57C-6 27 40 2 60 34c20-32 66-7 40 23Z" fill="currentColor"/><circle cx="47" cy="49" r="3" fill="var(--ink)"/><circle cx="72" cy="49" r="3" fill="var(--ink)"/><path d="M49 64q11 10 22 0" fill="none" stroke="var(--ink)" stroke-width="3"/>',book:'<path d="M21 17h73v88H21q-12-3-9-14V29q0-12 9-12" fill="currentColor"/><path d="M27 18v84" stroke="var(--ink)" stroke-width="3"/><path d="M43 43h34M43 55h25" stroke="var(--paper)" stroke-width="5"/><path d="m61 67 4 9 10 1-8 6 2 10-8-5-9 5 2-10-7-6 10-1Z" fill="var(--butter)"/>',search:'<circle cx="49" cy="45" r="31" fill="var(--sky)" stroke="currentColor" stroke-width="5"/><path d="m73 70 28 31" stroke="currentColor" stroke-width="13" stroke-linecap="round"/><circle cx="40" cy="41" r="3"/><circle cx="60" cy="41" r="3"/><path d="M42 56q9-6 16 0" stroke="var(--ink)" stroke-width="3" fill="none"/>'};
  return '<svg class="decoration '+className+'" viewBox="0 0 120 120" aria-hidden="true" focusable="false">'+(art[kind]||flower)+'</svg>';
}
export function coverDecoration(theme){return '<div class="cover-decoration" aria-hidden="true">'+(theme==='flower'?decoration('flower')+decoration('flower'):theme==='doodle'?decoration('star')+decoration('squiggle')+decoration('heart'):theme==='wavy'?'<svg viewBox="0 0 300 400" preserveAspectRatio="none"><path d="M-60-50Q240 65 15 190T60 450M40-50Q340 65 115 190T160 450M140-50Q440 65 215 190T260 450" fill="none" stroke="currentColor" stroke-width="45"/></svg>':'')+'</div>';}
